// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Proxy} from "../src/Proxy.sol";

contract InvMutTest is Test {
    Proxy c;
    function setUp() public { c = new Proxy(); }
    function testFuzz_property(address callee, bytes memory _data) public {
        vm.assume(callee != address(c));
        bool ok;
        try c.forward(callee, _data) { ok = true; } catch { ok = false; }
        (bool success,) = callee.call(_data);
        vm.assume(success);
        assertTrue(ok);
    }
}
